// Parse the LLM JSON, clamp values, attach route + SLA
const lead = $('Normalize lead').item.json;
let ai = {};
try { ai = JSON.parse($json.choices[0].message.content); } catch (e) { ai = {}; }
const tiers = ['Hot', 'Warm', 'Cold', 'Spam'];
const tier = tiers.includes(ai.tier) ? ai.tier : 'Cold';
const score = Math.max(0, Math.min(100, Math.round(Number(ai.score) || 0)));
const ROUTES = {
  Hot:  { action: 'AE call',          owner: 'Senior AE',            slack: '#sales-hot',  sla: 15 },
  Warm: { action: 'Nurture sequence', owner: 'SDR team',             slack: '#sales-warm', sla: 240 },
  Cold: { action: 'Nurture sequence', owner: 'Marketing automation', slack: '#sales-cold', sla: 1440 },
  Spam: { action: 'Disqualify',       owner: null,                   slack: null,          sla: null },
};
const r = ROUTES[tier];
const now = Date.now();
return [{ json: {
  ...lead,
  score, tier,
  confidence: Number(ai.confidence) || null,
  reasons: Array.isArray(ai.reasons) ? ai.reasons.slice(0, 6) : [],
  intent_signals: Array.isArray(ai.intent_signals) ? ai.intent_signals.slice(0, 8) : [],
  extracted: ai.extracted || {},
  reply_subject: ai.reply?.subject || '',
  reply_body: ai.reply?.body || '',
  route: r.action, owner: r.owner, slack_channel: r.slack,
  sla_minutes: r.sla,
  sla_due_at: r.sla ? new Date(now + r.sla * 60000).toISOString() : null,
  status: tier === 'Spam' ? 'archived' : 'new',
  processing_ms: now - new Date(lead.received_at).getTime(),
} }];

